<style>
.orbit-circle {
    transform-origin: 721.22px 272.76px; /* measured center of the whole pattern */
    will-change: transform;
}
.text-animation-introduction-v2{
    position: relative;
}
.art-wrap{
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    overflow: hidden;
}
.art-wrap svg {
    width: 100%;
    height: auto;
    min-height: 100dvh;
    transform: translateY(-110px);
}

.art-wrap:after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 50%;
    background: linear-gradient(180deg, rgba(18, 18, 18, 0) 0%, #121212 50%);
}
section.text-animation-introduction.text-animation-introduction-v2{
    height: auto;
    padding-bottom: 0;
}
.text-animation-introduction-v2 .introduction-content-container{
    justify-content: center;
    padding-top: 33dvh;
}
.text-animation-introduction-v2 .introduction-content-container .column{
    text-align: center;
    padding-right: 0 !important;
}
.text-animation-introduction-v2 .form-container-inner{
    justify-content: center;
}
.text-animation-introduction-v2 .button-container{
    width: auto !important;
    flex: 0 !important;
}
.text-animation-introduction-v2 .button-container a{
    margin-right: 0 !important;
    white-space: nowrap !important;
}
.text-animation-introduction-v2 span.animation-text-container .text {
    padding-left: calc((100% - 439px) / 2);
    padding-right: calc((100% - 439px) / 2);
}
section.text-animation-introduction-v2 .container .introduction-content-container .column.text-column .animation-text-container h1.heading-v2{
    font-size: 45px !important;
    line-height: 1 !important;
}
.heading-v2 span{
    color: #9A9A9A;
}
.heading-v2 span s{
    position: relative;
    text-decoration: none;
}
.heading-v2 span s svg{
    position: absolute;
    top: 50%;
    left: 10px;
    transform: translateY(-50%);
    width: 100%;
}
section.logo-ticker-tape .band-container-backwards:before, section.logo-ticker-tape .band-container-backwards:after {
    content: '';
    position: absolute;
    top: 0;
    bottom: 0;
    width: 100px;
    z-index: 2;
}
section.logo-ticker-tape .band-container-backwards{
    max-width: 1340px;
    margin: auto;
    justify-content: center;
    float: none;
}
    

section.logo-ticker-tape .band-container-backwards:before {
    left: 0;
    background: linear-gradient(90deg, #121212, transparent);
}
section.logo-ticker-tape .band-container-backwards:after {
    right: 0;
    background: linear-gradient(90deg, transparent, #121212);
}

@media (min-width: 1025px){
    section.text-animation-introduction .container .introduction-content-container .column.text-column .animation-text-container h1.heading-v2{
        font-size: 84px !important;
    }
}

@media (max-width: 1024px){
    .art-wrap svg {
        height: 100%;
        min-height: 1px;
        width: 768px;
        transform: translateX(-23%);
    }

    .art-wrap {
        bottom: unset;
        height: 500px;
        text-align: center;
    }

    .art-wrap:after { height: 70%;}

    .text-animation-introduction-v2 .introduction-content-container {
        padding-top: 20dvh;
    }
}
</style>
