<script nowprocket>
(function () {
  var orbits = document.querySelectorAll('.orbit-circle');

  var rotation = 0;          // current angle, degrees
  var idleSpeed = 0.0011;     // deg/ms — baseline speed when idle, clockwise (~1.1 deg/sec)
  var boost = 0;             // signed extra deg/ms on top of idle: +scrolling down, -scrolling up
  var scrollKick = 0.0011;   // deg/ms of boost added per px scrolled (either direction)
  var maxBoost = 0.008;       // cap so a huge flick-scroll doesn't spin it out of control
  var boostHalfLife = 400;   // ms for the boost to decay back toward 0 once scrolling stops

  function getScrollY() {
    return window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
  }

  var lastScrollY = getScrollY();
  var lastTime = performance.now();

  function applyRotation() {
    var t = 'rotate(' + rotation + 'deg)';
    for (var i = 0; i < orbits.length; i++) {
      orbits[i].style.transform = t;
    }
  }

  // Every scroll event gives the rotation an immediate speed "kick":
  // scrolling down speeds up clockwise, scrolling up reverses it
  // (spins counterclockwise), same sensitivity either way.
  function applyScrollKick(delta) {
    //boost += delta * scrollKick;
    //if (boost > maxBoost) boost = maxBoost;
    //if (boost < -maxBoost) boost = -maxBoost;
    if (delta <= 0) return;
    boost += delta * scrollKick;
    if (boost > maxBoost) boost = maxBoost;
  }

  window.addEventListener('scroll', function () {
    var y = getScrollY();
    var delta = y - lastScrollY;
    lastScrollY = y;
    applyScrollKick(delta);
  }, { passive: true });

  // Fallback for environments where 'scroll' doesn't fire reliably
  // (e.g. some embedded preview frames): also sample position every frame.
  function pollScroll(dt) {
    var y = getScrollY();
    var delta = y - lastScrollY;
    lastScrollY = y;
    applyScrollKick(delta);
  }

  function tick(now) {
    var dt = Math.min(now - lastTime, 100); // clamp huge gaps (tab switch, etc.)
    lastTime = now;

    pollScroll(dt);

    // exponential decay of the boost back toward zero
    var decay = Math.pow(0.5, dt / boostHalfLife);
    boost *= decay;

    // idle speed is clockwise; scroll boost can push it faster clockwise
    // (scrolling down) or reverse it counterclockwise (scrolling up)
    var speed = idleSpeed + boost;
    rotation += speed * dt;
    applyRotation();

    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
})();
</script>